package com.loyu3c.rental;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.time.*;
public class RentTermsTest {
    private JSONObject lease()throws Exception{return new JSONObject().put("id","L").put("unitId","U").put("tenant","測試").put("unitCodeSnapshot","101").put("start","2026-01-01").put("end","2026-12-31").put("dueDay",5).put("rent",10000).put("cycle","季繳").put("pricing","按月").put("firstDue","2026-01-05").put("termsVersion",1).put("utilities","管理者代收水電").put("water",200).put("electricRate",5);}
    @Test public void quarterHalfYearAndYearAmountsAndDueDates()throws Exception{JSONObject l=lease();JSONObject p=RentTerms.period(l,YearMonth.of(2026,5));assertEquals(30000,p.getLong("amount"));assertEquals("2026-04-05",p.getString("due"));assertEquals("2026-04-01",p.getString("from"));assertEquals("2026-06-30",p.getString("to"));assertEquals(60000,RentTerms.suggested(l.put("cycle","半年繳"),YearMonth.of(2026,7)));assertEquals(120000,RentTerms.suggested(l.put("cycle","年繳"),YearMonth.of(2026,12)));}
    @Test public void quarterRentIsNotChargedAgainButUtilitiesRemainMonthly()throws Exception{JSONObject l=lease();JSONObject jan=Ledger.monthlyPlan(l,YearMonth.of(2026,1),30000,200,100,110,new JSONArray(),new JSONArray());JSONArray bills=jan.getJSONArray("added");assertEquals(2,bills.length());JSONObject feb=Ledger.monthlyPlan(l,YearMonth.of(2026,2),30000,200,110,120,bills,new JSONArray());assertEquals(jan.getJSONObject("rent").getString("id"),feb.getJSONObject("rent").getString("id"));assertEquals(1,feb.getJSONArray("added").length());assertEquals("水電",feb.getJSONArray("added").getJSONObject(0).getString("kind"));assertEquals("2026-01-05",feb.getJSONObject("rent").getString("due"));}
    @Test public void dailyCrossMonthUsesInclusiveDaysAndSingleInvoice()throws Exception{JSONObject l=lease().put("start","2026-01-31").put("end","2026-02-01").put("rent",1000).put("pricing","按日").put("cycle","一次付清");RentTerms.validate(l);assertEquals(2000,RentTerms.suggested(l,YearMonth.of(2026,2)));assertEquals(YearMonth.of(2026,1),RentTerms.rentMonth(l,YearMonth.of(2026,2)));l.put("end","2026-01-31");assertEquals(1000,RentTerms.suggested(l,YearMonth.of(2026,1)));}
    @Test public void fixedPriceAndPartialMonthAndLeapYear()throws Exception{JSONObject l=lease().put("pricing","整段固定總價").put("cycle","一次付清").put("rent",4500);assertEquals(4500,RentTerms.suggested(l,YearMonth.of(2026,12)));l.put("pricing","按月").put("cycle","月繳").put("start","2024-02-15").put("end","2024-02-29").put("rent",2900);assertEquals(1500,RentTerms.suggested(l,YearMonth.of(2024,2)));}
    @Test public void invalidCombinationAndOverflowRejected()throws Exception{JSONObject l=lease().put("pricing","按日");try{RentTerms.validate(l);fail();}catch(IllegalArgumentException expected){}l.put("cycle","一次付清").put("rent",1000000000);try{RentTerms.suggested(l,YearMonth.of(2026,1));fail();}catch(IllegalArgumentException expected){}}
    @Test public void legacyInvoicesKeepMonthlyKeys()throws Exception{JSONObject l=lease();l.remove("termsVersion");assertEquals(YearMonth.of(2026,5),RentTerms.rentMonth(l,YearMonth.of(2026,5)));assertEquals(10000,RentTerms.suggested(l,YearMonth.of(2026,5)));}
}
